<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions';
import { useMasterDataLookupStore } from 'src/store/main';
import xmlTablePath from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/xmlTablePath.vue';
import xmlTableCreation from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/xmlTableCreation.vue';
import subOrgSelect from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/subOrgSelect.vue';
import dynamicApiValueTable from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/dynamicApiValueTable.vue';
import helperMixin from 'src/mixins/helperMixin';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
export default defineComponent({
  name: 'MasterDataLookup',
  components: {
    xmlTablePath,
    subOrgSelect,
    xmlTableCreation,
    dynamicApiValueTable,
  },
  mixins: [helperMixin],
  // Your Vue component logic goes here
  methods: {
    onRejected() {
      notify.error(
        this.$t('only_json_files_allowed'),
      );
    },
    checkFileType(files) {
       
      return files.filter(
        (file) => file.name.endsWith('.ionapi') || file.name.endsWith('.json'),
      );
    },
    handleUploadJson() {
      if (this.auth_json_file) {
        const reader = new FileReader();

        reader.onload = (e: any) => {
          const json_file = JSON.parse(e.target.result);
          this.endpoint_information['auth_json'] = e.target.result;
          if (this.endpoint_information['auth_type']['value'] == 'ionapi') {
            this.endpoint_information['url'] =
              json_file['iu'] + '/' + json_file['ti'];
          }
        };
        reader.readAsText(this.auth_json_file);
      } else if (this.endpoint_information['auth_json']) {
        const json_file = JSON.parse(this.endpoint_information['auth_json']);
        this.endpoint_information['url'] =
          json_file['iu'] + '/' + json_file['ti'];
      }
    },
    checkInputs() {
      if (!this.endpoint_information['url']) {
        return false;
      }
      if (!this.endpoint_information['data_type']) {
        return false;
      }

      if (this.endpoint_information['data_type'].includes(' ')) {
        return false;
      }

      return true;
    },
    selectPreset(preset) {
      if (!preset.id) {
        this.continueStepper(preset);
      }
      this.endpoint_information['method'] = {
        label: preset.method,
        value: preset.method,
      };
      if (preset.authentication_type == 'ionapi') {
        this.endpoint_information['auth_type'] = {
          label: 'ION API',
          value: 'ionapi',
        };
        this.endpoint_information['url_user_input'] = preset.url;
      }
      if (preset.authentication_type == 'oauth2') {
        this.endpoint_information['auth_type'] = {
          label: 'OAuth2',
          value: 'oauth2',
        };
        this.endpoint_information['url'] = preset.url;
      }
      if (preset.authentication_type == 'none') {
        this.endpoint_information['auth_type'] = {
          label: 'None',
          value: 'none',
        };
        this.endpoint_information['url'] = preset.url;
      }
      if (preset.authentication_json) {
        this.endpoint_information['auth_json'] = preset.authentication_json;
      }
      if (preset.is_dynamic) {
        this.endpoint_information['dynamic_api'] = true;
      }
      this.endpoint_information['data_type'] = preset.data_key;
      if (preset.sub_org_id) {
        this.endpoint_information['sub_org_id'] = preset.sub_org_id;
      }
      console.log(this.endpoint_information);

      let json_path = preset.data_base_path.replaceAll('$[', ' ');
      json_path = json_path.replaceAll('][', '.');
      json_path = json_path.replaceAll(']', '');
      json_path = json_path.trim();
      this.column_paths = [];
      this.endpoint_information['json_path'] = json_path;

      preset.column_paths = JSON.parse(preset.column_paths);
      Object.keys(preset.column_paths).forEach((key) => {
        this.column_paths.push({
          key: key,
          value: preset.column_paths[key],
        });
      });
      if (preset.body) {
        this.create_body = [];
        preset.body = JSON.parse(preset.body);
        Object.keys(preset.body).forEach((key) => {
          this.create_body.push({
            key: key,
            value: preset.body[key],
          });
        });
      }
      if (preset.headers) {
        this.create_headers = [];
        preset.headers = JSON.parse(preset.headers);
        Object.keys(preset.headers).forEach((key) => {
          this.create_headers.push({
            key: key,
            value: preset.headers[key],
          });
        });
      }
      if (preset.params) {
        this.create_parameters = [];
        preset.params = JSON.parse(preset.params);
        Object.keys(preset.params).forEach((key) => {
          this.create_parameters.push({
            key: key,
            value: preset.params[key],
          });
        });
      }
      this.api_tabs = 'auth';
      this.auth_json_file = null;
      this.handleUploadJson();
      if (this.endpoint_information.url_user_input) {
        this.endpoint_information.url_user_input =
          this.endpoint_information.url_user_input.replace(
            this.endpoint_information.url,
            '',
          );
      }

      (this.$refs.stepper as any)?.next?.();
    },
    async continueStepper(preset = 'none') {
      try {
        if (this.creation_step === 1) {
          const inputs_valid = this.checkInputs();
          if (!inputs_valid) {
            notify.error(this.$t('MISSING_FIELD'));
            return;
          }
          this.loading = true;
          if (this.endpoint_information['dynamic_api']) {
            const url = this.generateDynamicUrl();
            if (url instanceof Error) {
              throw url;
            }
            this.endpoint_information.url_user_input_formatted = url;
          }
          await this.testEndpointResponse('record');
          notify.success(
            this.$t('response_was_successful'),
          );
          (this.$refs.stepper as any)?.next?.();
          this.loading = false;
          return;
        }
        // if (this.creation_step === 3) {
        // }
        if (this.creation_step === 4) {
          if (this.column_paths.length === 0) {
            notify.error(
              this.$t('column_required'),
            );
            return;
          }
          this.loading = true;

          await this.testDataExtraction('record');
          notify.success(
            this.$t('response_was_successful'),
          );

          await this.createMasterData('record', this.mode);
          if (this.mode == 'edit') {
            notify.success(
              this.$t('master_data_updated'),
            );
            this.$router.push('/settings/master-data');
            return;
          }
          notify.success(
            this.$t('master_data_created'),
          );
          this.$router.push('/settings/master-data');
          this.loading = false;
        }

        if (this.creation_step === 0) {
          this.master_data_preset = preset;
          if (preset == 'reset') {
            this.resetAllFields();
            this.auth_json_file = null;
          }

          if (preset == 'ion_api_blank') {
            this.endpoint_information['method'] = {
              label: 'GET',
              value: 'GET',
            };
            this.endpoint_information['auth_type'] = {
              label: 'ION API',
              value: 'ionapi',
            };
            this.endpoint_information['data_type'] = 'new_ion_endpoint';
            this.api_tabs = 'auth';
            this.auth_json_file = null;
          }

          if (preset == 'oauth2') {
            this.endpoint_information['method'] = {
              label: 'GET',
              value: 'GET',
            };
            this.endpoint_information['auth_type'] = {
              label: 'OAuth2',
              value: 'oauth2',
            };
            this.endpoint_information['data_type'] = 'new_oauth2_endpoint';
            this.api_tabs = 'auth';
            this.auth_json_file = null;
          }
        }
        (this.$refs.stepper as any)?.next?.();
      } catch (e) {
        const message = ApiExceptions.getErrorMessage(e);
        this.loading = false;
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
    async testExtraction() {
      try {
        this.loading = true;
        await this.testDataExtraction('record');
      } catch (e) {
        const message = ApiExceptions.getErrorMessage(e);
        this.loading = false;
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
    addColumnToTable() {
      const response_json = JSON.parse(this.formatted_response_textarea);
      let is_valid = true;
      this.endpoint_information['column_value_name']
        .split(',')
        .forEach((column) => {
          var exists = response_json[0][column.replaceAll(' ', '')];
          if (exists == undefined) {
            is_valid = false;
          }
        });
      // const is_existing = response_json[0][this.endpoint_information['column_value_name']]

      if (!is_valid) {
        notify.error(
          this.$t(
            this.endpoint_information['column_value_name'] +
              ' Could not be found in your Response. Please check your JSON Path and try again.',
          ),
        );
        return;
      }
      if (this.column_paths.length === 0) {
        if (this.endpoint_information['column_name'].toLowerCase() != 'id') {
          notify.error(
            this.$t('column_id_required'),
          );
          return;
        }
      }
      this.column_paths.push({
        key: this.endpoint_information['column_name'],
        value: this.endpoint_information['column_value_name'],
      });
      this.endpoint_information['column_name'] = '';
      this.endpoint_information['column_value_name'] = '';
    },
    removeColumnFromTable(index) {
      this.column_paths.splice(index, 1);
    },
    addBodyToTable() {
      this.create_body.push({
        key: this.endpoint_information['query_body_key'],
        value: this.endpoint_information['query_body_value'],
      });
      this.endpoint_information['query_body_key'] = '';
      this.endpoint_information['query_body_value'] = '';
    },
    removeBodyFromTable(index) {
      this.create_body.splice(index, 1);
    },
    addHeaderToTable() {
      this.create_headers.push({
        key: this.endpoint_information['query_header_key'],
        value: this.endpoint_information['query_header_value'],
      });
      this.endpoint_information['query_header_key'] = '';
      this.endpoint_information['query_header_value'] = '';
    },
    removeHeaderFromTable(index) {
      this.create_headers.splice(index, 1);
    },
    addParamToTable() {
      this.create_parameters.push({
        key: this.endpoint_information['query_param_key'],
        value: this.endpoint_information['query_param_value'],
      });
      this.endpoint_information['query_param_key'] = '';
      this.endpoint_information['query_param_value'] = '';
    },
    removeParamFromTable(index) {
      this.create_parameters.splice(index, 1);
    },
    async getTemplates() {
      await this.getMasterDataList('template');
    },
    async getEndpoints() {
      await this.getMasterDataList('record');
    },
  },
  async mounted() {
    const endpoint_id = this.$route.params.id;
    await this.getEndpoints();
    if (endpoint_id) {
      this.creation_step = 1;
      this.mode = 'edit';
      this.auth_json_file = null;
      this.endpoint_information.id = endpoint_id;
      const row_index = this.custom_records.findIndex(
        (x: any) => x.id == endpoint_id,
      );
      if (row_index == -1) {
        this.router.push('/settings/master-data');
        return;
      }
      const row = this.custom_records[row_index];
      this.selectPreset(row);
    }
    this.getTemplates();
  },
  setup() {
    const master_data_store = useMasterDataLookupStore();
    const {
      create_parameters,
      custom_records,
      create_headers,
      data_mode,
      raw_json_response,
      create_body,
      column_paths,
      auth_options,
      endpoint_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,
      loading,
      custom_templates,
    } = storeToRefs(master_data_store);
    const {
      testEndpointResponse,
      updateDynamicUrl,
      beautifyJson,
      generateDynamicUrl,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
      getMasterDataList,
    } = master_data_store;
    return {
      beautifyJson,
      updateDynamicUrl,
      generateDynamicUrl,
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
      getMasterDataList,

      data_mode,
      custom_records,
      raw_json_response,
      custom_templates,
      loading,
      create_parameters,
      create_headers,
      create_body,
      column_paths,
      auth_options,
      endpoint_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,

      master_data_preset: ref(''),
      mode: ref('create'),
      auth_json_file: ref(null),
      creation_step: ref(0),
      api_tabs: ref('params'),
      stepper: 'stepper',
    };
  },
});
</script>
