<template>
  <span class="masterdata-tab-subheader">{{
    $t('dynamic_url_values')
  }}</span>
  <div class="flex items-center gap-2 q-mt-sm q-mb-sm">
    <q-btn @click="addNewRow" color="primary" icon="add" round flat dense>
      <q-tooltip>{{ $t('add_new') }}</q-tooltip>
    </q-btn>
  </div>
  <DocBitsTable
    :rows="dynamicApiSampleValues"
    :columns="tableColumns"
    row-key="key"
    table-id="dynamic_api_value_table"
    :features="{
      sorting: false,
      filtering: false,
      selection: false,
      bulkActions: false,
      rowActions: true,
      resizable: false,
      pagination: false,
      columnReorder: false,
      stickyLastColumn: true,
    }"
    :row-actions="rowActions"
    no-data-label="no_record_found"
    flat-style
    @row-action="handleRowAction"
  >
    <template #body-cell-field_name="{ row }">
      <q-input v-model="row.key" dense borderless />
    </template>
    <template #body-cell-sample_value="{ row }">
      <q-input v-model="row.value" dense borderless />
    </template>
  </DocBitsTable>
</template>
<script lang="ts">
import { defineComponent, ref, computed } from 'vue';
import { storeToRefs } from 'pinia';
import { useTranslate } from '@tolgee/vue';
import { useMasterDataLookupStore } from 'src/store/main';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  name: 'dynamicApiValueTable',
  components: { DocBitsTable },
  mounted() {
    this.dynamicApiSampleValues = this.getDynamicKeysByUrl();
  },
  setup() {
    const master_data_store = useMasterDataLookupStore();
    const { endpoint_information, dynamicApiSampleValues } =
      storeToRefs(master_data_store);
    const { getDynamicKeysByUrl } = master_data_store;

    const { t } = useTranslate();

    const tableColumns = computed(() => [
      {
        name: 'field_name',
        label: t.value('field_name'),
        align: 'left' as const,
        field: 'key',
      },
      {
        name: 'sample_value',
        label: t.value('value'),
        align: 'left' as const,
        field: 'value',
      },
    ] as UnifiedTableColumn[]);

    const rowActions: RowActionItem[] = [
      { key: 'delete', label: 'delete', icon: 'delete', color: 'negative' },
    ];

    return {
      tableColumns,
      endpoint_information,
      getDynamicKeysByUrl,
      dynamicApiSampleValues,
      rowActions,
    };
  },
  methods: {
    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        this.deleteRow(row);
      }
    },
    deleteRow(row: any) {
      const index = this.dynamicApiSampleValues.indexOf(row);
      this.dynamicApiSampleValues.splice(index, 1);
    },
    addNewRow() {
      this.dynamicApiSampleValues.push({
        key: '',
        value: '',
      });
    },
  },
});
</script>
